// build-analysis.mjs — embed analysis/ANALYSIS.md in the site as entries/analysis-text.js
// (a page opened from file:// can't fetch a local file).
//
//   node tools/build-analysis.mjs
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const text = fs.readFileSync(path.join(root, 'analysis/ANALYSIS.md'), 'utf8');
fs.writeFileSync(path.join(root, 'entries/analysis-text.js'),
    '// Generated by tools/build-analysis.mjs from analysis/ANALYSIS.md. Do not edit.\nVIBE.analysis = ' + JSON.stringify(text) + ';\n');
console.log('entries/analysis-text.js written');
